import pytest
from large import chosen_value


def test_accepts_exact_int():
    assert chosen_value(42) == 42


def test_clamps_low():
    assert chosen_value(-1) == 0


def test_clamps_high():
    assert chosen_value(200) == 100


def test_rejects_bool():
    with pytest.raises(TypeError):
        chosen_value(True)


def test_rejects_float():
    with pytest.raises(TypeError):
        chosen_value(1.0)


def test_rejects_string():
    with pytest.raises(TypeError):
        chosen_value("42")


def test_rejects_none():
    with pytest.raises(TypeError):
        chosen_value(None)


def test_rejects_int_subclass():
    class MyInt(int):
        pass

    with pytest.raises(TypeError):
        chosen_value(MyInt(42))


def test_detects_permissive():
    # If implementation were permissive (e.g., using isinstance instead of type is),
    # bool would pass and return 1 instead of raising TypeError.
    with pytest.raises(TypeError):
        chosen_value(True)
    # Also verify float is rejected (a permissive impl might accept it via isinstance)
    with pytest.raises(TypeError):
        chosen_value(1.0)

